'use strict';
const autonomyOnly=updateEnergy;
updateEnergy=function(){autonomyOnly();if(!records.length)return;const idx=dateIndex(),period=+$('solarPeriod').value,samples=records.slice(idx,idx+period).map(r=>evaluate(sites[+$('site').value],r,+$('height').value)),tracking=$('solarTracking').value==='tracking';$('panelAzimuth').disabled=tracking;$('panelTilt').disabled=tracking;const p={capacityWh:number('battery'),initialFraction:number('batteryInitial')/100,tracking,azimuth:number('panelAzimuth'),tilt:number('panelTilt'),areaM2:number('panelArea'),efficiency:number('panelEfficiency')/100,lossFraction:number('panelLoss')/100,irradiance:1361,stepHours:1,loadW:number('load'),chargeEfficiency:number('chargeEfficiency')/100},result=solarBudget(samples,p),sun=samples[0].sun,recommendedTilt=Math.max(0,Math.min(90,90-sun.el)),inc=tracking?incidenceFactor(sun.az,sun.el,sun.az,recommendedTilt):incidenceFactor(sun.az,sun.el,p.azimuth,p.tilt);$('solarAngles').innerHTML=`<div><small>AZIMUT SOLAR / GIRO HACIA EL SOL</small><b>${sun.az.toFixed(1)}°</b><span>0° norte · 90° este</span></div><div><small>INCLINACIÓN PARA INCIDENCIA NORMAL</small><b>${samples[0].sv?recommendedTilt.toFixed(1)+'°':'Sol oculto'}</b><span>Desde la horizontal; seguimiento ideal</span></div><div><small>APROVECHAMIENTO GEOMÉTRICO ACTUAL</small><b>${(samples[0].sv?inc*100:0).toFixed(1)} %</b><span>Distinto de la eficiencia eléctrica del panel</span></div>`;for(const[id,value]of [['solarGenerated',result.generatedWh],['solarCharged',result.chargedWh],['solarStored',result.finalStoredWh],['solarUnserved',result.unservedWh]])$(id).textContent=Math.round(value).toLocaleString('es-AR')+' Wh';$('solarCoverage').textContent=`Se calcularon ${samples.length} de ${period} horas solicitadas desde ${hoursLabel(idx)}. ${samples.length<period?'El archivo 2025 no cubre el período completo: los resultados son parciales. ':''}Capacidad utilizable: ${p.capacityWh} Wh; consumo constante: ${p.loadW} W. Horizonte LOLA muestreado dentro del radio seleccionado; las horas marginales se tratan conservadoramente.`;const peak=Math.max(1,...result.rows.map(r=>r.powerW)),x=i=>45+i/Math.max(1,result.rows.length-1)*820,y=w=>180-w/peak*145;let svg='';for(let i=0;i<=3;i++){const power=peak*i/3;svg+=`<line class="grid" x1="45" x2="865" y1="${y(power)}" y2="${y(power)}"/><text x="0" y="${y(power)+4}">${Math.round(power)} W</text>`;}svg+=`<path d="M45 180 L${result.rows.map((r,i)=>x(i)+' '+y(r.powerW)).join(' L')} L865 180Z" fill="#fbbf2420"/><path d="M${result.rows.map((r,i)=>x(i)+' '+y(r.powerW)).join(' L')}" fill="none" stroke="#fbbf24" stroke-width="1.5"/><text x="45" y="208">Inicio</text><text x="710" y="208">${samples.length} horas de modelo</text>`;$('solarPowerChart').innerHTML=svg;};
for(const id of ['solarTracking','panelAzimuth','panelTilt','panelArea','panelEfficiency','panelLoss','chargeEfficiency','batteryInitial','solarPeriod'])$(id).addEventListener('input',updateEnergy);if(records.length)updateEnergy();
